//! CCITT decoder tests (R5) — kept separate from `ccitt.rs` for the
//! 800-line module cap (R4). Encoded streams were generated by
//! `tests/gen_ccitt_fixtures.py` from `tests/ccitt-reference.js`
//! (pdf.js v3.11.174) and validated by running that reference decoder
//! under node; every *_EXPECT constant is what pdf.js itself emitted.
use super::*;
use crate::parser::objects::PdfObject;

fn parms(pairs: &[(&str, i64)]) -> FaxParms {
    let mut d: PdfDict = pairs
        .iter()
        .map(|(k, v)| (k.to_string(), PdfObject::Integer(*v)))
        .collect();
    // Test dict keys are inserted in order; sanity-check K exists.
    let _ = &mut d;
    FaxParms::from_dict(Some(&d)).expect("parms")
}

fn run(name: &str, stream: &[u8], p: &FaxParms, expect: &[u8]) {
    match decode_with(stream, p) {
        Ok(out) => assert_eq!(
            out,
            expect,
            "{name}: decoded {} bytes, expected {}",
            out.len(),
            expect.len()
        ),
        Err(e) => panic!("{name}: decode failed: {e}"),
    }
}

// V1: K=0, Columns=16. Rows: w5 b4 w7 | w2 b3 w11, trailing EOL. The
// trailing 0xaa byte is the reference's post-EOF phantom-row behaviour.
#[test]
fn one_d_rows_decode_runs() {
    const STREAM: [u8; 5] = [0xc7, 0xef, 0x20, 0x00, 0x40];
    const EXPECT: [u8; 5] = [0xf8, 0x7f, 0xc7, 0xff, 0xaa];
    run(
        "ONE_D",
        &STREAM,
        &parms(&[("K", 0), ("Columns", 16)]),
        &EXPECT,
    );
}

// V2: K=-1 (Group 4). Row0: HORZ w4 b4 from imaginary all-white ref;
// row1: VR1 (a1 = refLine[0]+1 = 5) + V0 -> w5 b3.
#[test]
fn group4_vertical_right_and_horizontal() {
    const STREAM: [u8; 4] = [0x36, 0xdc, 0x00, 0x40];
    const EXPECT: [u8; 3] = [0xf0, 0xf8, 0xff];
    run(
        "G4_VR1",
        &STREAM,
        &parms(&[("K", -1), ("Columns", 8)]),
        &EXPECT,
    );
}

// V3: K=-1. Row1 via VL1 + V0 -> w3 b5.
#[test]
fn group4_vertical_left() {
    const STREAM: [u8; 4] = [0x36, 0xd4, 0x00, 0x40];
    const EXPECT: [u8; 3] = [0xf0, 0xe0, 0xff];
    run(
        "G4_VL1",
        &STREAM,
        &parms(&[("K", -1), ("Columns", 8)]),
        &EXPECT,
    );
}

// V4: K=-1. Row1 via PASS -> w8 (passes over the ref's black run).
#[test]
fn group4_pass_mode() {
    const STREAM: [u8; 4] = [0x36, 0xc4, 0x00, 0x40];
    const EXPECT: [u8; 3] = [0xf0, 0xff, 0xff];
    run(
        "G4_PASS",
        &STREAM,
        &parms(&[("K", -1), ("Columns", 8)]),
        &EXPECT,
    );
}

// V5: K=-1. Two all-white rows from single V0 codes.
#[test]
fn group4_v0_two_rows() {
    const STREAM: [u8; 2] = [0xc0, 0x04];
    const EXPECT: [u8; 3] = [0xff, 0xff, 0xff];
    run(
        "G4_V0_2ROWS",
        &STREAM,
        &parms(&[("K", -1), ("Columns", 8)]),
        &EXPECT,
    );
}

// V6: K=1 with EOL + 1-D extension bit before each row.
#[test]
fn k1_with_eol_and_extension_bits() {
    const STREAM: [u8; 8] = [0x00, 0x1e, 0x3f, 0x00, 0x1b, 0xc8, 0x00, 0x10];
    const EXPECT: [u8; 5] = [0xf8, 0x7f, 0xc7, 0xff, 0xff];
    run(
        "K1_EOL",
        &STREAM,
        &parms(&[("K", 1), ("Columns", 16), ("EndOfLine", 1)]),
        &EXPECT,
    );
}

// V7: EncodedByteAlign — each row starts on a byte boundary.
#[test]
fn encoded_byte_align() {
    const STREAM: [u8; 2] = [0x7c, 0x1e];
    const EXPECT: [u8; 2] = [0xc0, 0x80];
    run(
        "BYTE_ALIGN",
        &STREAM,
        &parms(&[("K", 0), ("Columns", 4), ("EncodedByteAlign", 1)]),
        &EXPECT,
    );
}

// V8: BlackIs1 — output bits inverted (white = 0).
#[test]
fn black_is1_inverts_output() {
    const STREAM: [u8; 3] = [0xc7, 0xe0, 0x02];
    const EXPECT: [u8; 3] = [0x07, 0x80, 0x55];
    run(
        "BLACK_IS1",
        &STREAM,
        &parms(&[("K", 0), ("Columns", 16), ("BlackIs1", 1)]),
        &EXPECT,
    );
}

// V9: white makeup codes (75 = 64+11, 182 = 128+54). Columns=260.
#[test]
fn white_makeup_codes() {
    const STREAM: [u8; 5] = [0xda, 0x29, 0x12, 0x80, 0x08];
    const EXPECT: [u8; 34] = [
        0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xe3, 0xff, 0xff, 0xff, 0xff, 0xff,
        0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
        0xff, 0xff, 0xf0, 0xaa,
    ];
    run(
        "MAKEUP",
        &STREAM,
        &parms(&[("K", 0), ("Columns", 260)]),
        &EXPECT,
    );
}

// V10: black run 14 (code 00110000? no — 0001001100) + white 113.
#[test]
fn black_long_run() {
    const STREAM: [u8; 5] = [0x80, 0x7d, 0xa9, 0x00, 0x08];
    const EXPECT: [u8; 18] = [
        0xe0, 0x00, 0x7f, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
        0xff, 0xc0, 0xaa,
    ];
    run(
        "BLACK_LONG",
        &STREAM,
        &parms(&[("K", 0), ("Columns", 130)]),
        &EXPECT,
    );
}

// V11: /Rows truncates output to rows x ceil(columns/8) bytes (the
// reference decoder itself keeps going — our driver honours /Rows) and
// missing rows are white-padded.
#[test]
fn rows_param_limits_and_pads() {
    const STREAM: [u8; 5] = [0xc7, 0xef, 0x20, 0x00, 0x40];
    let p = FaxParms {
        k: 0,
        columns: 16,
        rows: 4,
        ..FaxParms::default()
    };
    let out = decode_with(&STREAM, &p).expect("decode");
    assert_eq!(out.len(), 4 * 2); // rows x stride
    assert_eq!(&out[..2], &[0xf8, 0x7f]); // first row intact
                                          // Rows 2.. decode from the same stream (row2 = phantom), rows 3.. pad.
    assert_eq!(out[2], 0xc7);
    assert_eq!(&out[6..], &[0xff, 0xff]); // white padding
}

// V12: truncated input — decoder tolerates damage like the reference
// (bad codes clamp to the row length; no panic, no error).
#[test]
fn truncated_stream_does_not_panic() {
    let p = parms(&[("K", 0), ("Columns", 1728)]);
    for cut in 0..4 {
        let out = decode_with(&[0xc7, 0xef, 0x20, 0x00, 0x40][..cut], &p);
        assert!(out.is_ok(), "cut {cut}: {:?}", out.err());
    }
    // Garbage input must not hang or panic either — output is bounded by
    // the row loop clamping to /Columns, then stops at EOF.
    let g = parms(&[("K", -1), ("Columns", 64)]);
    let out = decode_with(&[0x00, 0xff, 0x55, 0xaa, 0x13], &g).expect("garbage");
    assert!(out.len() < 1024, "garbage output runaway: {}", out.len());
}

// V13: invalid parameters are hard errors (R1/R7 style).
#[test]
fn invalid_parms_are_errors() {
    let d: PdfDict = [("Columns".to_string(), PdfObject::Integer(0))]
        .into_iter()
        .collect();
    assert!(FaxParms::from_dict(Some(&d)).is_err());

    let d: PdfDict = [("Rows".to_string(), PdfObject::Integer(-5))]
        .into_iter()
        .collect();
    assert!(FaxParms::from_dict(Some(&d)).is_err());

    let d: PdfDict = [("BlackIs1".to_string(), PdfObject::Name("true".into()))]
        .into_iter()
        .collect();
    assert!(FaxParms::from_dict(Some(&d)).is_err());

    // Defaults without parms.
    assert_eq!(FaxParms::from_dict(None).unwrap(), FaxParms::default());
}

// V14: stream-dict wiring — /Filter /CCITTFaxDecode with /DecodeParms
// decodes through PdfStream::decode (parms resolution path).
#[test]
fn stream_decode_uses_ccitt_parms() {
    use crate::parser::objects::PdfStream;
    let raw: Vec<u8> = vec![0xc7, 0xef, 0x20, 0x00, 0x40];
    let dict: PdfDict = [
        (
            "Filter".to_string(),
            PdfObject::Name("CCITTFaxDecode".into()),
        ),
        ("DecodeParms".to_string(), {
            PdfObject::Dictionary(
                [
                    ("K".to_string(), PdfObject::Integer(0)),
                    ("Columns".to_string(), PdfObject::Integer(16)),
                ]
                .into_iter()
                .collect(),
            )
        }),
    ]
    .into_iter()
    .collect();
    let stream = PdfStream {
        dict,
        raw_data: raw,
    };
    let out = stream.decode().expect("ccitt stream");
    assert_eq!(out, vec![0xf8, 0x7f, 0xc7, 0xff, 0xaa]);
}
